#include <iostream>

int ajustar(int nivel) {
    nivel = nivel * 2;
    return nivel - 1;
}

int main() {
    int nivel = 3;
    const int resultado = ajustar(nivel);
    std::cout << resultado << " " << nivel;
    return 0;
}

#include <iostream>

int contar_pasos(int repeticiones) {
    int cuenta = 0;
    for (int paso = 0; paso < repeticiones; ++paso) {
        ++cuenta;
    }
    return cuenta;
}

int main() {
    const int primera = contar_pasos(3);
    const int segunda = contar_pasos(1);
    std::cout << primera << " " << segunda;
    return 0;
}

#include <iostream>

int preparar(int base) {
    int salida = 0;
    if (base > 0) {
        const int parcial = base + 2;
        salida = parcial;
    }
    return salida;
}

int main() {
    std::cout << preparar(4);
    return 0;
}

